def is_inside_service_area(latitude, longitude):
    if isinstance(latitude, bool) or isinstance(longitude, bool):
        return False
    try:
        y, x = float(latitude), float(longitude)
    except (TypeError, ValueError, OverflowError):
        return False
    if not math.isfinite(y) or not math.isfinite(x):
        return False
    inside = False
    for (ay, ax), (by, bx) in zip(CITY_RING_SNAPSHOT, CITY_RING_SNAPSHOT[1:]):
        cross = (x-ax)*(by-ay)-(y-ay)*(bx-ax)
        if (abs(cross) < 1e-10 and min(ax,bx)-1e-10 <= x <= max(ax,bx)+1e-10
                and min(ay,by)-1e-10 <= y <= max(ay,by)+1e-10):
            return True
        if (ay > y) != (by > y) and x < (bx-ax)*(y-ay)/(by-ay)+ax:
            inside = not inside
    return inside


def canonical_pickup(place):
    """Validate an actual selected food venue and return its stable snapshot."""
    if not isinstance(place, dict) or place.get("kind") != "restaurant":
        raise ValueError("اختار مطعمًا أو مكان طعام، وليس جهة رعاية.")
    lat = place.get("latitude", place.get("lat"))
    lon = place.get("longitude", place.get("lon"))
    if not is_inside_service_area(lat, lon):
        raise ValueError("موقع المطعم خارج نطاق المشروع أو إحداثياته غير صالحة.")
    name = str(place.get("name") or "").strip()
    if not name or name in {"اسم غير مسجّل", "مكان بدون اسم مسجّل"}:
        raise ValueError("المكان بدون اسم مسجّل؛ اختار مطعمًا معروفًا من القائمة.")
    lat, lon = float(lat), float(lon)
    place_id = place.get("place_id")
    if not place_id:
        if place.get("directory_id"):
            place_id = "YP-" + str(place["directory_id"])
        elif place.get("osm_id"):
            place_id = "OSM-" + str(place["osm_id"])
        else:
            raw = f"{name}|{lat:.7f}|{lon:.7f}"
            place_id = "PLACE-" + hashlib.sha256(raw.encode()).hexdigest()[:20]
    return {
        "place_id": str(place_id), "kind": "restaurant", "name": name,
        "address": str(place.get("address") or "").strip(),
        "latitude": lat, "longitude": lon,
        "source": str(place.get("source") or "مصدر منشور"),
    }


def get_restaurants():
    result = {}
    for place in EXTRA_RESTAURANTS:
        try:
            selected = canonical_pickup(place)
        except ValueError:
            continue
        result.setdefault(selected["place_id"], selected)
    return list(result.values())


def match_restaurant_at_point(places, point, tooltip=None):
    """Accept exact marker clicks only; ambiguous co-located venues need a list choice."""
    if not isinstance(point, dict):
        return None
    try:
        lat, lon = float(point["lat"]), float(point["lng"])
    except (KeyError, TypeError, ValueError, OverflowError):
        return None
    if not isinstance(tooltip, str) or not tooltip.strip():
        return None
    label = html.unescape(re.sub(r"<[^>]*>", "", tooltip)).strip()
    matches = {}
    for place in places:
        if place.get("kind") != "restaurant":
            continue
        try:
            selected = canonical_pickup(place)
        except ValueError:
            continue
        if selected["name"] != label:
            continue
        if abs(selected["latitude"]-lat) < 1e-7 and abs(selected["longitude"]-lon) < 1e-7:
            matches[selected["place_id"]] = selected
    return next(iter(matches.values())) if len(matches) == 1 else None
